#define ANGLE 4.
#define DENSITY 5.

#define PPX (24.*8.)
#define MOD3 vec3(.1031,.11369,.13787)

float random(vec2 p) {
   return fract(sin(dot(p.xy, vec2(12.9898,78.233))) *
    43758.5453123);
}

float voronoi(vec2 uv, float density, float angle) {
    vec2 g  = fract(uv * density);
    vec2 f  = floor(uv * density);

    float d = 8.;
    for(int x=-1; x<=1; x++) {
        for(int y=-1; y<=1; y++) {
            vec2 cell = vec2(x, y);
            vec2 rv   = vec2(sin(random(f+cell) * max(1., angle))*0.5+0.5, cos(random(f+cell) * max(1., angle))*0.5+0.5);

            float dist = distance(cell + rv, g);
            if(dist < d) {
                d = dist;
            }
        }
    }

    return d;
}

float worley(vec2 uv, int octaves, float lacunarity, float persistance, float density, float offset) {

    float amplitude = 0.5;
    float frequency = 1.;

    float y = 0.;
    for(int o = 0; o < octaves; o++) {
        float of = float(o);
        y += amplitude * (1.-voronoi(frequency*uv, density, offset + of));
        frequency *= lacunarity;
        amplitude *= persistance;
    }

    return y;
}

vec3 hash33(vec3 p3)
{
	p3 = fract(p3 * MOD3);
    p3 += dot(p3, p3.yxz+19.19);
    return -1.0 + 2.0 * fract(vec3((p3.x + p3.y)*p3.z, (p3.x+p3.z)*p3.y, (p3.y+p3.z)*p3.x));
}

float noise3d(vec3 p)
{
    vec3 pi = floor(p);
    vec3 pf = p - pi;

    vec3 w = pf * pf * (3.0 - 2.0 * pf);

    return 	mix(
        		mix(
                	mix(dot(pf - vec3(0, 0, 0), hash33(pi + vec3(0, 0, 0))), 
                        dot(pf - vec3(1, 0, 0), hash33(pi + vec3(1, 0, 0))),
                       	w.x),
                	mix(dot(pf - vec3(0, 0, 1), hash33(pi + vec3(0, 0, 1))), 
                        dot(pf - vec3(1, 0, 1), hash33(pi + vec3(1, 0, 1))),
                       	w.x),
                	w.z),
        		mix(
                    mix(dot(pf - vec3(0, 1, 0), hash33(pi + vec3(0, 1, 0))), 
                        dot(pf - vec3(1, 1, 0), hash33(pi + vec3(1, 1, 0))),
                       	w.x),
                   	mix(dot(pf - vec3(0, 1, 1), hash33(pi + vec3(0, 1, 1))), 
                        dot(pf - vec3(1, 1, 1), hash33(pi + vec3(1, 1, 1))),
                       	w.x),
                	w.z),
    			w.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;

    uv.y += cos(iTime*.2)*.02;
    uv.x -= sin(iTime*.2)*.02;

    uv -= .5;
    uv.x *= iResolution.x / iResolution.y;

    uv *= PPX;
    uv = floor(uv) / PPX;

    vec3 col = vec3(0.);

    float f = 1. + noise3d(vec3((uv*DENSITY), .6));
    f *= (1. + worley(uv, 6, 1.65, .6, DENSITY, iTime*.3));
    f /= (DENSITY / 2.);
    f = clamp(pow(f, 6.) * 4., 0., 1.);

    if(f >= .3) {
        col = 1.2*vec3(56./255., 19./255., 144./255.);

        if(f >= .9) {
            col = 1.4*vec3(56./255., 19./255., 144./255.);
        }        
    } else {
        float mask = mod((uv.x * PPX) + mod((uv.y * PPX), 2.0), 2.0);
        col = vec3(((1.-step(f, .1)) * mask) *(f*4.)* vec3(57./255., 19./255., 144./255.));
    }



    fragColor = vec4(col, 1.0);
}
